content.text:
.meter>i{display:block;height:100%;width:0;background:#d18b58;transition:width .15s}
.meter.heat>i{background:linear-gradient(90deg,#6e986f,#d5a856,#cf6554)}
.card-label{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#9da99c;margin:18px 0 9px}
.hero-mini{display:flex;align-items:center;gap:10px;padding:9px;background:#202923;border:1px solid #3a453b}
.avatar{width:38px;height:42px;background:#54584c;position:relative;overflow:hidden;border:1px solid #88794e}
.avatar:before{content:"";position:absolute;width:18px;height:18px;border-radius:50%;background:#c59b75;top:7px;left:10px}
.avatar:after{content:"";position:absolute;width:30px;height:25px;border-radius:50% 50% 0 0;background:#27302a;bottom:-6px;left:4px}
.hero-mini strong{display:block;font:600 12px 'Playfair Display',serif}
.hero-mini span{font:9px 'DM Mono',monospace;color:#9aa59a}
.bottom-note{font:10px/1.5 'DM Mono',monospace;color:#758078;margin-top:16px}
.game-panel{min-width:0;background:#101613;border:1px solid #475044;box-shadow:0 12px 50px #0007;position:relative}
.game-head{height:43px;padding:0 14px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(90deg,#242d27,#18201c);border-bottom:1px solid #39433a}
.district{font:10px 'DM Mono',monospace;letter-spacing:.14em;color:#cdbb8c}
.weather{font:9px 'DM Mono',monospace;color:#879489}
.canvas-wrap{position:relative;width:100%;aspect-ratio:1.52;background:#121b18;overflow:hidden}
.canvas-wrap canvas{display:block;width:100%;height:100%;touch-action:none}
.canvas-label{position:absolute;left:12px;top:12px;font:9px 'DM Mono',monospace;color:#d4c9a8;background:#111713b8;padding:6px 8px;border:1px solid #62634d80;letter-spacing:.1em;pointer-events:none}
--
.game-foot{height:42px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;background:#151c18;border-top:1px solid #303a33}
.foot-tip{font-size:10px;color:#8d998e}
.foot-tip b{font:10px 'DM Mono',monospace;color:#dac486;font-weight:400}
.controls{display:flex;gap:6px}
.key{font:9px 'DM Mono',monospace;padding:4px 6px;border:1px solid #566052;color:#d1c7a6;background:#1a221d;min-width:24px;text-align:center}
.right{padding:18px 15px}
.right h2{font:600 20px 'Playfair Display',serif;margin:6px 0 4px}
.right-desc{font-size:10px;color:#8e9b90;line-height:1.5;margin:0 0 12px}
.roster{display:flex;flex-direction:column;gap:6px;max-height:430px;overflow:auto;padding-right:2px}
.hero-choice{width:100%;display:flex;align-items:center;gap:9px;text-align:left;background:#1b241f;border:1px solid #303b33;padding:7px;transition:.18s;position:relative}
.hero-choice:hover{border-color:#938256;background:#232c25}
.hero-choice.active{border-color:#c3a45d;background:#2b3026;box-shadow:inset 2px 0 #d8b76e}
.portrait{width:36px;height:38px;flex:none;position:relative;overflow:hidden;border:1px solid #6b6952;background:linear-gradient(145deg,var(--p1),var(--p2))}
--
.action-btn:hover{background:#3a3b2b;border-color:#bc9f5d}
.action-btn.primary{background:#9e8150;color:#171914;border-color:#d6b66e;font-weight:500}
.action-btn.primary:hover{background:#c0a266}
.toast{position:absolute;left:50%;top:54px;transform:translate(-50%,-8px);z-index:4;padding:9px 14px;background:#131a16ef;border:1px solid #b59c61;color:#e7d8b4;font:10px 'DM Mono',monospace;letter-spacing:.04em;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.touch-controls{display:none}

@media(max-width:1120px){.layout{grid-template-columns:220px minmax(0,1fr)}
.right{grid-column:1/-1}
.roster{display:grid;grid-template-columns:repeat(4,1fr);max-height:none}
.hero-choice{min-height:52px}
.right{padding:14px}
.right-head{display:flex;align-items:end;justify-content:space-between}
--
.layout{grid-template-columns:1fr;gap:10px}
.left{padding:13px 15px;display:grid;grid-template-columns:1fr 1fr;gap:0 14px}
.left h1{font-size:23px}
.left .rule,.bottom-note,.card-label,.hero-mini{display:none}
.objective{grid-column:1/-1}
.obj-row{margin:5px 0}
.statusline{margin:7px 0}
.objective>.eyebrow{margin-bottom:4px}
.right{grid-column:auto}
.right-head{display:block}
.right-desc{max-width:none}
.roster{grid-template-columns:repeat(2,1fr);gap:5px}
--
.game-head{height:36px}
.game-foot{height:auto;min-height:38px}
.foot-tip{font-size:9px}
.controls{display:none}
.canvas-wrap{aspect-ratio:1.18}
.touch-controls{position:absolute;inset:auto 0 8px;display:flex;justify-content:space-between;align-items:end;padding:0 7px;pointer-events:none}
.touch-group{display:flex;gap:3px;pointer-events:auto}
.touch-btn{width:38px;height:38px;border-radius:50%;background:#131a16cf;border:1px solid #94845d;color:#e6d9b8;font:9px 'DM Mono',monospace;touch-action:none;padding:0}
.touch-btn.big{width:46px;height:46px}
.toast{top:43px;font-size:9px}
.actionbar{margin-top:8px}
}

